INSERT INTO reviewed_plant_passports VALUES
 (103,'Драцена Розовая','{"repotting":"Пересаживайте весной, когда корни заполнят горшок, в ёмкость лишь немного шире прежней. Слишком большой запас влажного грунта повышает риск загнивания корней."}'::jsonb),
 (114,'Кактус Микс','{"repotting":"Пересаживайте весной, если корни заполнили горшок или растение переросло его. Выбирайте небольшой горшок с отверстиями и рыхлый грунт для кактусов; при работе с колючками защитите руки."}'::jsonb),
 (115,'Кактус (с цветками)','{"repotting":"Пересаживайте весной, когда корни заполнят горшок, в ёмкость лишь немного больше прежней. Нужны дренажные отверстия и рыхлый грунт для кактусов; не пересаживайте только ради цветения."}'::jsonb),
 (122,'Кордилина','{"repotting":"Весной проверьте, хватает ли корням места. При тесном горшке перевалите кордилину в чуть большую ёмкость с отверстиями; у крупного растения можно обновить верхний слой грунта."}'::jsonb),
 (164,'Пальмы микс (Арека и Хамедорея)','{"repotting":"Комнатные пальмы пересаживайте ранней весной, только если корни заполнили горшок. Новый горшок берите немного больше прежнего и сохраняйте корневой ком; у крупных экземпляров обновляйте верхний слой грунта."}'::jsonb),
 (181,'Соланум (Паслен)','{"repotting":"Если растение сохраняют после сезона, пересаживайте весной при тесном горшке. Используйте ёмкость немного больше прежней с дренажными отверстиями и свежим рыхлым грунтом; не травмируйте корни без необходимости."}'::jsonb),
 (187,'Суккулент (микс)','{"repotting":"Пересаживайте весной, когда корни заполнили горшок или растение стало неустойчивым. Возьмите ёмкость немного больше прежней, с отверстиями и хорошо дренируемым грунтом для суккулентов."}'::jsonb),
 (241,'Шеффлера','{"repotting":"Весной проверьте корневой ком: если корни плотно оплели грунт, перевалите растение в горшок немного больше прежнего. Используйте рыхлый грунт для комнатных растений и ёмкость с дренажными отверстиями."}'::jsonb),
 (242,'Шеффлера (Герда)','{"repotting":"Весной проверьте корневой ком: если корни плотно оплели грунт, перевалите растение в горшок немного больше прежнего. Используйте рыхлый грунт для комнатных растений и ёмкость с дренажными отверстиями."}'::jsonb),
 (243,'Шеффлера Луизиана','{"repotting":"Весной проверьте корневой ком: если корни плотно оплели грунт, перевалите растение в горшок немного больше прежнего. Используйте рыхлый грунт для комнатных растений и ёмкость с дренажными отверстиями."}'::jsonb),
 (40,'Араукария','{"repotting":"Переваливайте весной, только когда корни заполнили горшок. Возьмите ёмкость немного больше прежней с хорошим дренажом; старайтесь сохранить корневой ком и прежнюю глубину посадки."}'::jsonb),
 (51,'Бонсай Азалия','{"repotting":"Пересаживайте бонсай при уплотнении субстрата и тесноте корней, обычно после цветения или в подходящий весенний период. Сохраняйте неглубокую ёмкость и кислый субстрат для азалий; обрезку корней проводите осторожно."}'::jsonb),
 (53,'Бонсай Азалия мелколистная','{"repotting":"Пересаживайте бонсай при уплотнении субстрата и тесноте корней, обычно после цветения или в подходящий весенний период. Сохраняйте неглубокую ёмкость и кислый субстрат для азалий; обрезку корней проводите осторожно."}'::jsonb),
 (54,'Бонсай Араукария','{"repotting":"Пересаживайте весной, когда корни заполнят плошку и субстрат станет плотным. Осторожно перевалите в хорошо дренируемую смесь, сохранив большую часть корневого кома; сильную обрезку корней не проводите."}'::jsonb),
 (57,'Бонсай Зантоксилум','{"repotting":"Проверяйте состояние корней и субстрата каждую весну. Пересаживайте при тесной плошке или уплотнённом грунте, осторожно обновляя дренируемую смесь и сохраняя достаточно корней для восстановления."}'::jsonb),
 (58,'Бонсай Зелкова','{"repotting":"Пересаживайте весной до активного роста, если корни плотно заполнили плошку или грунт уплотнился. Используйте дренируемый субстрат для бонсай и осторожно работайте с корнями."}'::jsonb),
 (76,'Бонсай Подокарпус','{"repotting":"Осматривайте корневой ком весной и пересаживайте, когда плошка стала тесной или субстрат потерял рыхлость. Возьмите хорошо дренируемую смесь для бонсай; не удаляйте слишком много корней за один раз."}'::jsonb),
 (78,'Бонсай Радермахера','{"repotting":"Пересаживайте весной, если корни заполнили плошку и вода плохо проходит через субстрат. Обновите рыхлую дренируемую смесь, сохранив основную часть корневого кома; после пересадки берегите от пересыхания."}'::jsonb),
 (81,'Бонсай Самшит прямой','{"repotting":"Пересаживайте весной при тесной плошке или уплотнённом субстрате. Осторожно обновите дренируемую смесь и корни, сохранив достаточный объём корневого кома для восстановления растения."}'::jsonb),
 (853,'Араукария 20 см D10','{"repotting":"Переваливайте весной, только когда корни заполнили горшок. Возьмите ёмкость немного больше прежней с хорошим дренажом; старайтесь сохранить корневой ком и прежнюю глубину посадки."}'::jsonb),
 (864,'Бонсай Фисташка D15','{"repotting":"Весной проверьте, не заполнили ли корни плошку. При тесноте пересадите в дренируемый субстрат для бонсай, аккуратно работая с корнями; не увеличивайте объём сырого грунта резко."}'::jsonb),
 (88,'Гибискус','{"repotting":"Пересаживайте весной, когда корни заполнят горшок, в ёмкость немного больше прежней с дренажными отверстиями. Используйте свежий рыхлый грунт для цветущих комнатных растений и не заглубляйте основание стебля."}'::jsonb);
